; c06_alu_shift -- ALU SHL / SHR
; Layer-1 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: the direction bit shift_dir (D6: is 0 SHL or SHR?); the amount field; signed_mode; SHL exact to 24 bits
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: c06_alu_shift.expected.csv
.include "conf_defs.inc"
.main
    MOV CONST(0x8001, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0000, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU SHL 1 unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 0, len=4, ptr=8
    ALU SHR 1 unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 4, len=4, ptr=8
    ALU SHL 1 signed
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 8, len=4, ptr=8
    ALU SHR 1 signed
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 12, len=4, ptr=8
    ALU SHL 8 unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 16, len=4, ptr=8
    ALU SHR 8 unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 20, len=4, ptr=8
    ALU SHL 3 unsigned
    MOV ALU_OUT[0..3] -> MAIN_SCRATCHPAD[8..11]
    EXEC_CSR WRITE_SP RES + 24, len=4, ptr=8
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
